import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:]

    last_pos = {}
    ans = N + 1

    for i, x in enumerate(A, start=1):
        if x in last_pos:
            length = i - last_pos[x] + 1
            if length < ans:
                ans = length
        last_pos[x] = i

    if ans == N + 1:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    main()
```
